47	    static final class SingleElementSubscriber<T>
48	    implements FlowableSubscriber<T>, Disposable {
49	
50	        final SingleObserver<? super T> downstream;
51	
52	        final T defaultValue;
53	
54	        Subscription upstream;
55	
56	        boolean done;
57	
58	        T value;
59	
60	        SingleElementSubscriber(SingleObserver<? super T> actual, T defaultValue) {
61	            this.downstream = actual;
62	            this.defaultValue = defaultValue;
63	        }
