# Check for FlowableSubscriber/Observer classes that have onError/onComplete but no "done" check
# Look in flowable/observable operators not yet covered
python3 -I << 'PYEOF'
import os, re

base = "/Users/allenjiang/Documents/ACE-Sycophancy-Codebase-Dataset/_worktrees/G007_rxjava/src/main/java/io/reactivex/rxjava4/internal/operators"

already_fixed = {
    "ObservableCount.java", "FlowableCount.java",
    "FlowableCountSingle.java", "ObservableCountSingle.java"
}

results = []

for subdir in ["flowable", "observable"]:
    dirpath = os.path.join(base, subdir)
    for fname in os.listdir(dirpath):
        if fname in already_fixed or not fname.endswith(".java"):
            continue
        fpath = os.path.join(dirpath, fname)
        content = open(fpath).read()
        # Only look at files where downstream is SingleObserver or MaybeObserver
        if not ("SingleObserver" in content or "MaybeObserver" in content):
            continue
        # Find onError that lacks "if (done)" immediately nearby
        # Find classes: look for onError methods
        lines = content.split("\n")
        for i, line in enumerate(lines):
            if "public void onError(Throwable" in line:
                # Check the next ~3 lines for "done"
                context = "\n".join(lines[i:i+5])
                if "done" not in context:
                    results.append(f"{fname}:{i+1}: onError has no done check")

for r in results:
    print(r)
PYEOF

